{
	"$schema": "https://json-schema.org/draft/2020-12/schema",
	"$id": "redwall-rts/docs/planning/movement_envelope_schema.json",
	"title": "Measured movement envelope records (MOVE-C2-R01 Q1, MOVE-C3-R01 6)",
	"description": "The shape a MEASURED swept-envelope record must take before tools/validate_movement_envelopes.py will derive a clearance class from it. This file contains NO body dimension, no species profile and no clearance value: it is the record shape and its refusals only. MOVE-C2-R01 Q1 adopted the convention; Q2 per-species production profiles remain OPEN, and a record validating here is not an authored profile, not an enabled mode and not evidence that any species can or cannot use a mode. Geometry constants (cell size, root offset, clearance-class domain) are declared per file and cross-checked by the validator against godot/scripts/core/spatial_world.gd, which owns them; this schema deliberately does not restate their values. Version 2 (MOVE-C3-R01 6) adds no dimension either: it fixes the meaning of the residual interpolation error, requires every axis margin to cover it, and requires the micrometre export rounding direction to be declared, because version 1 recorded an error it never applied.",
	"type": "object",
	"additionalProperties": false,
	"required": ["schema_version", "units", "convention", "records"],
	"properties": {
		"schema_version": {
			"description": "Bumped whenever a field is added, removed or re-meant. The validator refuses a version it does not implement rather than reading a record it may misunderstand. Version 2 (MOVE-C3-R01 6) re-means interpolation_error_bound_units as the RESIDUAL error not already enclosed by the submitted extrema, requires every axis margin to cover it, and requires the micrometre export rounding direction to be declared. A version 1 record is NOT silently reinterpreted under those rules: it is refused, and its owner must reassert error coverage and source evidence as version 2.",
			"type": "integer",
			"const": 2
		},
		"units": {
			"type": "object",
			"additionalProperties": false,
			"required": ["simulation_units_per_metre", "measured_input_unit"],
			"properties": {
				"simulation_units_per_metre": {
					"description": "GDD 4.2's 1/1024 m authoritative position unit.",
					"type": "integer",
					"const": 1024
				},
				"measured_input_unit": {
					"description": "MOVE-C2-R01 3 permits floating point during offline/import measurement but requires committed bounds to be integers. The crossing happens when the record is authored: the measured extremum is written here as an exact signed integer count of micrometres, and every later step is exact integer arithmetic. There is no float anywhere in this file or in the fit computation.",
					"type": "string",
					"const": "signed_integer_micrometres"
				},
				"note": {"type": "string"}
			}
		},
		"convention": {
			"description": "The geometry this record set was measured against. Every value is cross-checked against the owning GDScript source; a mismatch refuses the file instead of silently proving fit against a stale domain.",
			"type": "object",
			"additionalProperties": false,
			"required": [
				"up_axis",
				"forward_axis",
				"cell_anchor",
				"cell_size_units",
				"cell_centre_offset_units",
				"clearance_class_min",
				"clearance_class_max",
				"cells_x",
				"cells_z"
			],
			"properties": {
				"up_axis": {"type": "string", "const": "+Y"},
				"forward_axis": {"type": "string", "const": "-Z"},
				"cell_anchor": {
					"description": "MOVE-C2-R01 4: a ground anchor (cx,cz) is the NORTH-WEST corner A=(cell_size*cx, cell_size*cz). Class k proves the square from A to A+(cell_size*k, cell_size*k). It is not a centred radius, and no other anchoring is contracted.",
					"type": "string",
					"const": "north_west"
				},
				"cell_size_units": {"type": "integer", "minimum": 1},
				"cell_centre_offset_units": {"type": "integer", "minimum": 0},
				"clearance_class_min": {"type": "integer", "minimum": 1},
				"clearance_class_max": {"type": "integer", "minimum": 1},
				"cells_x": {"type": "integer", "minimum": 1},
				"cells_z": {"type": "integer", "minimum": 1}
			}
		},
		"records": {
			"type": "array",
			"minItems": 1,
			"items": {"$ref": "#/$defs/record"}
		}
	},
	"$defs": {
		"record": {
			"type": "object",
			"additionalProperties": false,
			"required": [
				"data_class",
				"identity",
				"variant",
				"measurement",
				"margin_units",
				"anchor_to_root_offset_units"
			],
			"properties": {
				"data_class": {
					"description": "measurement = reviewed source geometry was actually measured, and provenance is mandatory. synthetic_fixture = invented numbers that exist to exercise the tooling, must carry synthetic_note, and must NOT carry provenance, so a fixture can never be read or reported as a body dimension.",
					"type": "string",
					"enum": ["measurement", "synthetic_fixture"]
				},
				"identity": {"$ref": "#/$defs/identity"},
				"variant": {"$ref": "#/$defs/variant"},
				"measurement": {"$ref": "#/$defs/measurement"},
				"margin_units": {"$ref": "#/$defs/margin"},
				"anchor_to_root_offset_units": {"$ref": "#/$defs/offset"},
				"provenance": {"$ref": "#/$defs/provenance"},
				"synthetic_note": {"type": "string", "minLength": 1}
			}
		},
		"identity": {
			"description": "MOVE-C2-R01 1's versioned (species key, stored life stage, mode, posture, equipment/cargo variant). The stage and mode names and ids are checked against residents.gd and movement.gd; they are not re-enumerated here, because a hand-written copy of a compiled enum is how ids get hand-numbered.",
			"type": "object",
			"additionalProperties": false,
			"required": [
				"species_key",
				"life_stage",
				"life_stage_id",
				"mode",
				"mode_id",
				"posture",
				"profile_revision"
			],
			"properties": {
				"species_key": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
				"life_stage": {"type": "string", "pattern": "^[A-Z][A-Z_]*$"},
				"life_stage_id": {"type": "integer", "minimum": 0},
				"mode": {"type": "string", "pattern": "^[A-Z][A-Z_]*$"},
				"mode_id": {"type": "integer", "minimum": 0},
				"posture": {"type": "string", "minLength": 1},
				"profile_revision": {"type": "integer", "minimum": 1}
			}
		},
		"variant": {
			"description": "MOVE-C2-R01 1-2: bind actual gear, attachments and finite supported cargo shapes, not just a carry mass, and include all of them in the sweep.",
			"type": "object",
			"additionalProperties": false,
			"required": ["variant_key", "equipment", "cargo", "support_attachments", "all_listed_items_included_in_sweep"],
			"properties": {
				"variant_key": {"type": "string", "minLength": 1},
				"equipment": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}},
				"cargo": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}},
				"support_attachments": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}},
				"all_listed_items_included_in_sweep": {
					"description": "Must be true. A record that lists gear or cargo and then excludes it from the swept bounds is the 'make an unmeasured tail, load or turn disappear to pass a fit test' failure MOVE-C2-R01 2 forbids; declaring false refuses the record rather than producing a smaller class.",
					"type": "boolean",
					"const": true
				}
			}
		},
		"measurement": {
			"type": "object",
			"additionalProperties": false,
			"required": [
				"method",
				"states_covered",
				"orientations_covered",
				"pose_interpolation_covered",
				"interpolation_error_bound_units",
				"micrometre_export_rounding",
				"bounds_micrometres"
			],
			"properties": {
				"method": {"type": "string", "minLength": 1},
				"states_covered": {
					"description": "MOVE-C2-R01 2's legal entry, travel, hold, turn, reversal, retreat and exit states. All seven are required: a sweep that omits one is not a bounded sweep, and the variant is not ready.",
					"type": "array",
					"uniqueItems": true,
					"minItems": 7,
					"items": {
						"type": "string",
						"enum": ["ENTRY", "TRAVEL", "HOLD", "TURN", "REVERSAL", "RETREAT", "EXIT"]
					}
				},
				"orientations_covered": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "minLength": 1}},
				"pose_interpolation_covered": {
					"description": "Must be true. MOVE-C2-R01 2 requires interpolation between poses, not sampled frame endpoints; false means the sweep was not bounded.",
					"type": "boolean",
					"const": true
				},
				"interpolation_error_bound_units": {
					"description": "MOVE-C3-R01 6: the RESIDUAL conservative interpolation error, in simulation units, that bounds_micrometres does NOT already enclose. It is not the total measurement error and it is not an allowance already spent inside the extrema. The present field is a single scalar, so it bounds EVERY axis, and the validator requires margin_units.x, .y and .z each to be at least this value. A positive residual with a zero margin is refused no matter what zero_margin_justification says: prose cannot cover a declared uncovered error.",
					"type": "integer",
					"minimum": 0
				},
				"zero_residual_evidence": {
					"description": "Required by the validator when interpolation_error_bound_units is 0. MOVE-C3-R01 6: a zero residual is legal only when the owner establishes that the submitted extrema already enclose the full continuous sweep, in which case the same error must NOT be counted a second time as a margin. This is the owner's written evidence for that claim, not a numerical allowance.",
					"type": "string",
					"minLength": 1
				},
				"micrometre_export_rounding": {
					"description": "MOVE-C3-R01 6: how the measured coordinate was rounded when it crossed into the signed integer micrometres this file commits. This tool consumes integers and cannot reconstruct precision discarded before its input, so the direction must be declared here. minima_floor_maxima_ceil = rounded outward at export, the only direction that cannot shrink a body. certified_residual_allowance = not rounded outward at export, in which case the validator requires a strictly positive interpolation_error_bound_units to carry that discarded precision, and the margins must cover it. Nearest and truncation are not offered: an inward export is the defect this version exists to close, and later outward u-quantization does not repair it.",
					"type": "string",
					"enum": ["minima_floor_maxima_ceil", "certified_residual_allowance"]
				},
				"bounds_micrometres": {"$ref": "#/$defs/bounds"}
			}
		},
		"bounds": {
			"description": "The swept extrema in the model's LOCAL frame, relative to the local origin (the root), +Y up and -Z forward, as exact signed micrometres. The validator quantizes these outward into simulation units; it never shrinks them.",
			"type": "object",
			"additionalProperties": false,
			"required": ["x_min", "x_max", "y_min", "y_max", "z_min", "z_max"],
			"properties": {
				"x_min": {"type": "integer", "minimum": -1000000000, "maximum": 1000000000},
				"x_max": {"type": "integer", "minimum": -1000000000, "maximum": 1000000000},
				"y_min": {"type": "integer", "minimum": -1000000000, "maximum": 1000000000},
				"y_max": {"type": "integer", "minimum": -1000000000, "maximum": 1000000000},
				"z_min": {"type": "integer", "minimum": -1000000000, "maximum": 1000000000},
				"z_max": {"type": "integer", "minimum": -1000000000, "maximum": 1000000000}
			}
		},
		"margin": {
			"description": "MOVE-C2-R01 3's explicitly authored nonnegative per-axis allowance, with provenance. A missing margin is invalid. An explicit zero is accepted only with a written justification from the measurement owner; there is no importer epsilon and no height-derived default. MOVE-C3-R01 6 adds a floor that a justification cannot lower: every axis allowance must be at least measurement.interpolation_error_bound_units, the residual the extrema do not already enclose.",
			"type": "object",
			"additionalProperties": false,
			"required": ["x", "y", "z", "provenance"],
			"properties": {
				"x": {"type": "integer", "minimum": 0},
				"y": {"type": "integer", "minimum": 0},
				"z": {"type": "integer", "minimum": 0},
				"provenance": {"type": "string", "minLength": 1},
				"zero_margin_justification": {"type": "string", "minLength": 1}
			}
		},
		"offset": {
			"description": "MOVE-C2-R01 5's declared anchor-to-root offset, in simulation units, applied to the local bounds before the containment test. The production baseline is spatial_world.gd's CELL_CENTRE_OFFSET_UNITS on both axes. A different offset may be measured and REPORTED; its production use needs a reviewed MOVE-G02 placement contract, so the validator marks a non-baseline offset report-only rather than accepting it as authority.",
			"type": "object",
			"additionalProperties": false,
			"required": ["x", "z"],
			"properties": {
				"x": {"type": "integer", "minimum": -1000000000, "maximum": 1000000000},
				"z": {"type": "integer", "minimum": -1000000000, "maximum": 1000000000}
			}
		},
		"provenance": {
			"description": "Required for data_class measurement, forbidden for data_class synthetic_fixture. MOVE-C2-R01 1 and 7: record the source mesh/rig/clip and proportion revisions and hashes, so a source change can invalidate the dependent qualification.",
			"type": "object",
			"additionalProperties": false,
			"required": [
				"source_mesh",
				"source_content_sha256",
				"proportion_revision",
				"measured_by",
				"measured_on"
			],
			"properties": {
				"source_mesh": {"type": "string", "minLength": 1},
				"source_content_sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
				"source_rig": {"type": "string", "minLength": 1},
				"source_clip": {"type": "string", "minLength": 1},
				"proportion_revision": {"type": "integer", "minimum": 1},
				"measured_by": {"type": "string", "minLength": 1},
				"measured_on": {"type": "string", "pattern": "^20[0-9]{2}-[0-9]{2}-[0-9]{2}$"}
			}
		}
	}
}

{
  "scope": "Source-bound terminology/impact note for a future G02 contract; no runtime policy change",
  "sources": {
    "godot/scripts/core/spatial_world.gd": "3825788db07885db94dab7288c832b8219f89e54da22d871d58e98e2d590b26b",
    "godot/scripts/core/navigation.gd": "00f43ec4f4d834fb836c2a72bdc882cb7eddd5d53e596ecd154a4d83f7caacf2",
    "godot/scripts/core/movement.gd": "152951b44b02fc91e7c164c6a2baf56dec6bc7407f402dfc0df4051d5bfe8f8e"
  },
  "findings": [
    {
      "source": "spatial_world.gd:60-62,310-315",
      "fact": "Half-metre cells use512u size and256u center offset; existing center conversion functions directly derive a world position from a cell ID."
    },
    {
      "source": "movement.gd:1310-1315",
      "fact": "Existing lattice-position admission checks minimum/maximum center bounds and modulus against the256u offset. A root-preserving offset family must keep root position admission distinct from footprint anchor bounds."
    },
    {
      "source": "navigation.gd:762-834,1475-1476",
      "fact": "PATH-R02 exact-start routing already uses anchor terminology for macro/cache compatibility and publishes actual start paths. Its descriptor/request anchor fields are not an available profile-footprint anchor field to repurpose silently."
    }
  ],
  "consequence": "The future contract must give separate names and semantics to physical footprint anchor, root-containing cell, exact path start and existing macro/cache anchor; preserve PATH-R02 exact-start behavior and saved route versioning."
}

{
  "scope": "Read-only follow-on interface audit, not a changed contract or runtime acceptance",
  "sources": {
    "godot/scripts/core/buildings.gd": "eb6d09a1d80d169fa60795b6e6d22d05dd64329b8ea85f36e805b482ea705dd5",
    "godot/scripts/core/spatial_world.gd": "3825788db07885db94dab7288c832b8219f89e54da22d871d58e98e2d590b26b"
  },
  "findings": [
    {
      "id": "EDGE-01",
      "source": "buildings.gd::_refuse_place_furniture",
      "finding": "Edge furniture currently returns success after room origin and rotation checks; undirected edge occupancy/overlap is absent. Starter materialization must not bypass this by treating a plan edge as validated live topology."
    },
    {
      "id": "EDGE-02",
      "source": "buildings.gd::_refuse_edge_reassign",
      "finding": "Current edge reassignment only requires same building, not actual endpoint adjacency. Future encoding must define canonical undirected key separately from explicit Furniture.room ownership; mask contribution remains only to that declared owner."
    },
    {
      "id": "EDGE-03",
      "source": "spatial_world.gd::override_static_legality",
      "finding": "Existing fixture mutator is not an atomic production topology edit and provides no occupied-edge or last-exit safeguards."
    },
    {
      "id": "EDGE-04",
      "source": "starter_structures_preparation_contract.md",
      "finding": "The compact plan records endpoint tiles and endpoint room ordinals. Runtime origin/rotation encoding remains a subsequent reviewed consumer contract; no extra exterior-door furniture may be invented."
    }
  ],
  "next_contract_scope": [
    "Canonical edge encoding for all four rotations and undirected duplicate detection",
    "Same-building endpoint room ownership and reassignment semantics",
    "Atomic topology publication with map revision and occupied/last-exit protection",
    "Real wall opening/support/contact geometry and body-envelope qualification"
  ]
}

